using System;using System.Xml.Linq;
class Program {
 static int count;static void Test(string n,Func<bool> f){if(!f())throw new Exception(n);count++;Console.WriteLine("PASS "+n);}
 static void Main(){
 Test("public version",()=>global::Main.BepInExPluginVersion=="2.2.3");Test("display no beta",()=>global::Main.PluginShowVersion=="2.2.3");Test("product stable",()=>global::Main.PluginReleaseVersion=="2.2.3");Test("update comparison",()=>global::Main.ShellVersion>new Version("2.2.2"));Test("wire unchanged",()=>global::Main.PluginVersion=="4.00.40.00");Test("tag carries release",()=>global::Main.VersionCheckTag=="same-commit(same-branch)/Shell-2.2.3");
 global::Main.playerVersion[1]=new(global::Main.version,global::Main.VersionCheckTag,global::Main.ForkId);Test("same build accepted",()=>Gate.MatchVersions(1));
 foreach(var tag in new[]{"same-commit(same-branch)","same-commit(same-branch)/Shell-2.2.1","other(same-branch)/Shell-2.2.3"}){global::Main.playerVersion[1]=new(global::Main.version,tag,global::Main.ForkId);Test("incompatible tag rejected "+tag,()=>!Gate.MatchVersions(1));}
 global::Main.playerVersion[1]=new(global::Main.version,global::Main.VersionCheckTag,"other");Test("other fork rejected",()=>!Gate.MatchVersions(1));global::Main.playerVersion[1]=new(new Version("4.00.39.00"),global::Main.VersionCheckTag,global::Main.ForkId);Test("other wire rejected",()=>!Gate.MatchVersions(1));Test("Vanilla allowed explicitly",()=>Gate.MatchVersions(2,true));Test("unknown mod not assumed same",()=>!Gate.MatchVersions(2));
 var root=Environment.GetEnvironmentVariable("TOHS_VERSION_SOURCE");var xml=XDocument.Load(Path.Combine(root,"TownOfHost.csproj"));foreach(var p in new[]{("Version","2.2.3"),("AssemblyVersion","2.2.3.0"),("FileVersion","2.2.3.0"),("InformationalVersion","2.2.3")})Test("project "+p.Item1,()=>xml.Descendants(p.Item1).Single().Value==p.Item2);
 var rpc=File.ReadAllText(Path.Combine(root,"Modules/RPC.cs"));Test("sender and local cache share tag",()=>rpc.Contains("writer.Write(Main.VersionCheckTag)")&&rpc.Contains("new PlayerVersion(Main.PluginVersion, Main.VersionCheckTag, Main.ForkId)"));Test("legacy major-version parser retained",()=>rpc.Contains("3 <= version.Major ? reader.ReadString() : Main.OriginalForkId"));Test("lobby display shares tag",()=>File.ReadAllText(Path.Combine(root,"Patches/PlayerContorols/FixedUpatePatch.cs")).Contains("ver.tag == Main.VersionCheckTag"));Test("updater uses public version",()=>File.ReadAllText(Path.Combine(root,"Modules/ModUpdater.cs")).Contains("latestVersion.CompareTo(Main.ShellVersion)"));foreach(var tag in new[]{"v2.2.3","v2.2.3","v2.2.1β","2.2.3","v2.3.0"})Test("release tag parser "+tag,()=>TownOfHost.Modules.ShellReleaseMetadata.ParseVersion(tag)!=null);Test("invalid tag rejected",()=>TownOfHost.Modules.ShellReleaseMetadata.ParseVersion("invalid")==null);Test("release list uses same parser",()=>File.ReadAllText(Path.Combine(root,"Modules/ModUpdater.cs")).Contains("ShellReleaseMetadata.ParseVersion(tag) == null"));var actualMain=File.ReadAllText(Path.Combine(root,"main.cs"));
foreach(var pair in new[]{("BepInExPluginVersion",global::Main.BepInExPluginVersion),("PluginShowVersion",global::Main.PluginShowVersion),("PluginReleaseVersion",global::Main.PluginReleaseVersion),("PluginVersion",global::Main.PluginVersion)})Test("actual source constant "+pair.Item1,()=>actualMain.Contains("public const string "+pair.Item1+" = \""+pair.Item2+"\";"));
global::Main.playerVersion[1]=new(global::Main.version,"same-commit(same-branch)/Shell-2.2.2",global::Main.ForkId);Test("prior Shell 2.2.2 rejected",()=>!Gate.MatchVersions(1));
Test("stable next release ordering",()=>TownOfHost.Modules.ShellReleaseMetadata.ParseVersion("v2.2.3")>new Version("2.2.2"));
Test("historical credits preserved",()=>File.ReadAllText(Path.Combine(root,"Credits.md")).Contains("旧TOH-hamo"));
Test("old main project version removed",()=>!File.ReadAllText(Path.Combine(root,"TownOfHost.csproj")).Contains("<Version>2.1.0</Version>"));
Console.WriteLine($"RESULT {count} passed, 0 failed");}}
